class NullParamPolicy(str, Enum):
    """What a null in a per-row expression parameter means.

    Deliberately separate from :class:`RowErrorPolicy`: under ``NULL`` a null
    parameter is not an error, so it records no ``_error`` message and does not
    weaken reporting for genuine decode/encode/operation failures.
    - RAISE: a null parameter fails the expression.
    - NULL: the affected node produces no output for that row.
    """

    RAISE = "raise"
    NULL = "null"


class PadMode(str, Enum):
    """Padding mode selection.

    Controls how padding values are determined:
    - CONSTANT: Fill with a constant value (default)
    - EDGE: Replicate edge values
    - REFLECT: Reflect values at edge (not including edge)
    - SYMMETRIC: Reflect values at edge (including edge)
    """

    CONSTANT = "constant"
    EDGE = "edge"
    REFLECT = "reflect"
    SYMMETRIC = "symmetric"


class PadPosition(str, Enum):
    """Position for pad_to_size.

    Controls where the original content is placed:
    - CENTER: Center content in padded area (default)
    - TOP_LEFT: Place content at top-left corner
    - BOTTOM_RIGHT: Place content at bottom-right corner
    """

    CENTER = "center"
    TOP_LEFT = "top-left"
    BOTTOM_RIGHT = "bottom-right"


class RowErrorPolicy(str, Enum):
    """What a failing row does to a graph query.

    Applies to errors raised while producing a row — source decode, op
    execution, output encode:
    - RAISE: propagate the first error, failing the whole expression.
    - NULL: a failing row yields null; other rows proceed.
    - NULL_WITH_MESSAGE: as NULL, plus an `_error` field.
    """

    RAISE = "raise"
    NULL = "null"
    NULL_WITH_MESSAGE = "null_with_message"


