class _OpsMixin:
    """The generated builder methods ``Pipeline`` inherits."""

    if TYPE_CHECKING:

        def _append_typed(self, op_name: str, values: dict[str, Any]) -> Pipeline: ...
        def _with_source(self, format: str, values: dict[str, Any]) -> Pipeline: ...

    def source(
        self,
        format: str = "auto",
        *,
        allowed_roots: Sequence[str] | None = None,
        cloud_options: CloudOptions | dict[str, Any] | None = None,
        decode_max_size: int | None = None,
        dtype: str | None = None,
        on_error: str | None = None,
        require_contiguous: bool | None = None,
    ) -> Pipeline:
        """Define the input source format.

        The default ``"auto"`` infers the decode path from the column's Polars
        dtype at runtime. Pass an explicit format to override the inference (or
        when the column dtype cannot be routed, such as a plain numeric column).

        Image sources (``"image_bytes"`` and ``"file_path"``) auto-detect the
        encoding and preserve its dtype: PNG/JPEG decode to u8, 16-bit PNG to u16,
        and TIFF may produce u8, u16, f32 or f64. Decoded images are always 3D
        ``[H, W, C]``. Until then the dtype is ``"auto"``: a ``list``/``array``
        sink needs it known at planning time, from ``dtype=`` here, a ``cast()``,
        or an operation that fixes it.

        A ``"contour"`` source decodes to the contour domain; rasterize it with
        :meth:`rasterize`.

        Each keyword applies to some formats and not others, and defaults to
        ``None`` (the format's own default). One that does not apply to the chosen
        format is **rejected**, naming the formats it applies to.

        ``decode_max_size`` asserts the pipeline needs at most this many pixels on
        the decoded long side, so JPEG decoding uses IDCT scaling (1/8, 1/4 or
        1/2) to skip work. The long side never drops below
        ``min(decode_max_size, original)``, so a downstream resize to that size
        never upscales; other encodings decode at full size. A scaled decode
        followed by a resize is not bit-identical to a full decode and the same
        resize, hence the explicit opt-in.

        ``allowed_roots`` restricts which locations a path column may read from.
        An entry that parses as a remote URI (``"s3://bucket/public/"``) is
        matched as a URI prefix, anything else (``"/srv/images"``) as a local
        directory. Local paths are canonicalized first, so ``..`` and symlinks
        cannot escape, and matching is component-wise (``"/srv/images"`` does not
        admit ``"/srv/images-private"``). A path matching no entry is refused, and
        the refusal is subject to ``on_error``.

        Args:
            format: How to decode the input column. ``array``: A Polars fixed-size
                `Array` column, one nesting level per axis. ``auto``: Infer the decode
                path from the column's Polars dtype: String → file_path, List/Array →
                list/array, Binary → blob if VIEW-tagged else image_bytes. ``blob``: The
                self-describing VIEW protocol. ``contour``: A contour column (one
                contour or a set per row), decoded as the contour set `extract_contours`
                produces. A mask is the `rasterize` op's. ``file_path``: A path (local,
                s3://, gs://, az://, http://) whose contents decode like image bytes.
                ``image_bytes``: Encoded image bytes (PNG/JPEG/TIFF/...), always decoded
                to `[H, W, C]`. ``list``: A Polars nested `List` column, one nesting
                level per axis; its sizes may differ from row to row. ``raw``: Raw
                bytes, decoded as a flat 1-D buffer of `dtype`.
            allowed_roots: ``auto``, ``file_path``: Locations a path column may read
                from (unrestricted when absent; see above).
            cloud_options: ``auto``, ``file_path``: Cloud-storage credentials: a
                ``CloudOptions`` or a dict.
            decode_max_size: ``auto``, ``file_path``, ``image_bytes``: Decode only
                enough pixels for this long side (JPEG IDCT scaling; see above).
            dtype: ``array``, ``list``: Element dtype; inferred from the column when
                absent. ``auto``: Asserted element dtype (a decoded image is cast to
                it). ``blob``: Declared element dtype. A blob carries its own, so a
                declaration is checked at decode: a blob of another dtype is a row
                error. ``file_path``, ``image_bytes``: Asserted element dtype: a decoded
                image with another dtype is cast. ``raw``: The element dtype: raw bytes
                carry no type metadata, so it is required.
            on_error: ``array``, ``auto``, ``blob``, ``contour``, ``image_bytes``,
                ``list``, ``raw``: "raise" or "null": what a row that cannot be decoded
                does. ``file_path``: "raise" or "null": what a row that cannot be read
                or decoded does.
            require_contiguous: ``array``, ``list``: Require rectangular data (zero-
                copy); jagged rows are then an error. ``auto``: Require rectangular data
                when the column is a List/Array.

        Example:
            ```python
            >>> # Decode PNG/JPEG bytes from a column
            >>> pipe = Pipeline().source("image_bytes").resize(height=224, width=224)
            >>>
            >>> # Read from file paths or URLs, sandboxed
            >>> pipe = Pipeline().source("file_path", allowed_roots=["/srv/images"])
            >>>
            >>> # Assert dtype for a list sink (cast if needed at runtime)
            >>> pipe = Pipeline().source("image_bytes", dtype="f32")
            >>>
            >>> # Gracefully handle corrupt images as null
            >>> pipe = Pipeline().source("image_bytes", on_error="null")
            >>>
            >>> # Rasterize a contour column to a mask
            >>> pipe = Pipeline().source("contour").rasterize(width=64, height=64)
            ```
        """
        return self._with_source(
            format,
            {
                "allowed_roots": allowed_roots,
                "cloud_options": cloud_options,
                "decode_max_size": decode_max_size,
                "dtype": dtype,
                "on_error": on_error,
                "require_contiguous": require_contiguous,
            },
        )

    def abs(self) -> Pipeline:
        """Absolute value (`|x|`).

        Domain: buffer → buffer
        """
        return self._append_typed("abs", {})

    def add_constant(self, value: FloatOrExpr) -> Pipeline:
        """Add a constant to every value (`x + value`).

        Domain: buffer → buffer

        Args:
            value: Constant addend (literal or per-row expression).
        """
        return self._append_typed("add_constant", {"value": value})

    def adjust_contrast(self, factor: FloatOrExpr) -> Pipeline:
        """Adjust image contrast: `(pixel - mean) * factor + mean`.

        Domain: buffer → buffer

        Args:
            factor: Contrast factor. 1.0 = no change, >1 = more contrast, <1 = less.

        Example:
            >>> pipe = Pipeline().source("image_bytes").adjust_contrast(factor=1.5)
        """
        return self._append_typed("adjust_contrast", {"factor": factor})

    def adjust_gamma(self, gamma: FloatOrExpr) -> Pipeline:
        """Apply gamma (power-law) correction: normalize to [0,1], raise to `gamma`,
        denormalize.

        Domain: buffer → buffer

        Args:
            gamma: Gamma value. <1 = brighter, >1 = darker, 1.0 = no change.

        Example:
            >>> pipe = Pipeline().source("image_bytes").adjust_gamma(gamma=0.5)
        """
        return self._append_typed("adjust_gamma", {"gamma": gamma})

    def apply_lut(
        self, table: Sequence[Sequence[FloatOrExpr]], *, out_dtype: str = "u8"
    ) -> Pipeline:
        """Map each value through a lookup table.

        Each u8 or u16 value is a row index into ``table``. Rows of one entry map
        every element in place, on any channel count (as ``cv2.LUT`` with one
        table); rows of ``K > 1`` entries take a single-channel image to ``K``
        channels (a palette). The entries are stored as ``out_dtype``. A value with no
        row is an error for its row: clamp first, keeping the dtype
        (``clamp(0, len(table) - 1, out_dtype="u8")``), to send the excess to the
        last row.

        Domain: buffer → buffer

        Args:
            table: The rows, indexed by value: 1 to 65536 of them, each of the same
                length (1, or the palette's channel count). Each entry must fit
                ``out_dtype``, and may be a Polars expression; the lengths are literal.
            out_dtype: The output element dtype the entries are stored as.

        Example:
            >>> heat = Pipeline().source("image_bytes").grayscale().apply_lut([[v, 0, 255 - v] for v in range(256)])
        """
        return self._append_typed("apply_lut", {"table": table, "out_dtype": out_dtype})

    def _assert_shape(
        self, dims: Sequence[IntOrExpr | None], *, exact: bool = True
    ) -> Pipeline:
        """Declare the shape of the data at this point: sizes of its dimensions,
        and with them its rank when the declaration is exact.

        The planner applies the declaration (refusing one it contradicts), and
        execution checks it against every row, so everything downstream rests on a
        checked fact. The public `Pipeline.assert_shape` is sugar over this op.

        Domain: buffer → buffer, vector → vector

        Args:
            dims: The size of each dimension from the first; `None` declares nothing
                about that dimension. A per-row size is checked per row and is no plan-
                time fact.
            exact: Whether `dims` is the whole shape, so the rank is its length
                (`assert_shape(dims=[...])`), or only its leading dimensions
                (`assert_shape(height=, width=, channels=)`).
        """
        return self._append_typed("assert_shape", {"dims": dims, "exact": exact})

    def blur(self, sigma: FloatOrExpr) -> Pipeline:
        """Apply Gaussian blur.

        Domain: buffer → buffer

        Args:
            sigma: Standard deviation for Gaussian kernel.
        """
        return self._append_typed("blur", {"sigma": sigma})

    def canny(
        self, *, low_threshold: FloatOrExpr = 50.0, high_threshold: FloatOrExpr = 150.0
    ) -> Pipeline:
        """Canny edge detection, as ``cv2.Canny(image, low, high)`` computes it:
        3x3 Sobel gradients (L1 magnitude), non-maximum suppression and
        double-threshold hysteresis. There is no pre-blur — add ``.blur()``
        first for a smoothed edge map, as with OpenCV. A colour image uses, per
        pixel, the channel with the strongest gradient; alpha is ignored. Output
        is a U8 binary edge map (0 or 255).

        Domain: buffer → buffer

        Args:
            low_threshold: Lower hysteresis threshold.
            high_threshold: Upper hysteresis threshold.

        Example:
            >>> edges = Pipeline().source("image_bytes").blur(sigma=1.4).canny(low_threshold=50, high_threshold=150)
        """
        return self._append_typed(
            "canny", {"low_threshold": low_threshold, "high_threshold": high_threshold}
        )

    def cast(self, dtype: str) -> Pipeline:
        """Cast to a different data type.

        Domain: buffer → buffer

        Args:
            dtype: Target data type (e.g., "f32", "u8").
        """
        return self._append_typed("cast", {"dtype": dtype})

    def ceil(self) -> Pipeline:
        """Round toward positive infinity.

        Domain: buffer → buffer
        """
        return self._append_typed("ceil", {})

    def channel_select(self, index: IntOrExpr) -> Pipeline:
        """Extract a single channel from a multi-channel image: a 2D [H, W] buffer
        from a [H, W, C] input.

        Domain: buffer → buffer

        Args:
            index: Channel index to extract (0-based). Accepts a Polars expression for
                per-row dynamic selection.

        Example:
            >>> pipe = Pipeline().source("image_bytes").channel_select(index=0)  # Red channel
        """
        return self._append_typed("channel_select", {"index": index})

    def channel_swap(self, order: Sequence[IntOrExpr]) -> Pipeline:
        """Reorder channels in a multi-channel image.

        Domain: buffer → buffer

        Args:
            order: New channel ordering, e.g. [2, 1, 0] for RGB-to-BGR. **Each index may
                be a literal or a Polars expression**, so the permutation can vary per
                row. The list *length* is the channel count and must be literal.

        Example:
            >>> pipe = Pipeline().source("image_bytes").channel_swap(order=[2, 1, 0])
        """
        return self._append_typed("channel_swap", {"order": order})

    def _clamp(self, *, min: FloatOrExpr, max: FloatOrExpr) -> Pipeline:
        """Clamp values to a range.

        The public `Pipeline.clamp` is sugar over this op that adds
        `out_dtype`/`preserve_dtype` (a trailing cast).

        Domain: buffer → buffer

        Args:
            min: Minimum value (literal or expression).
            max: Maximum value (literal or expression).
        """
        return self._append_typed("clamp", {"min": min, "max": max})

    def clamp_max(self, value: FloatOrExpr) -> Pipeline:
        """Cap values at `value` (`min(x, value)`); one-sided clamp.

        Domain: buffer → buffer

        Args:
            value: Upper bound (literal or per-row expression).
        """
        return self._append_typed("clamp_max", {"value": value})

    def clamp_min(self, value: FloatOrExpr) -> Pipeline:
        """Floor values at `value` (`max(x, value)`); one-sided clamp.

        Domain: buffer → buffer

        Args:
            value: Lower bound (literal or per-row expression).
        """
        return self._append_typed("clamp_min", {"value": value})

    def area(self, *, signed: BoolOrExpr = False) -> Pipeline:
        """Compute the area of the contour using the Shoelace formula.

        The area of the region the contour describes: the exterior minus the
        union of its hole rings, in either winding direction. Overlapping or
        nested hole rings are not double-subtracted. One value per contour for
        a contour set.

        Domain: contour → vector

        Args:
            signed: If True, return signed area (negative for CW winding).
        """
        return self._append_typed("contour_area", {"signed": signed})

    def boundary(self) -> Pipeline:
        """A region's rings as open lines: the exterior, then each hole, each
        returning to its first point. The result is a set (holes add rings);
        an open contour, already a line, is refused.

        Domain: contour → contour
        """
        return self._append_typed("contour_boundary", {})

    def bounding_box(self) -> Pipeline:
        """Compute the axis-aligned bounding box of the contour.

        Returns ``[x, y, width, height]``.

        Domain: contour → vector
        """
        return self._append_typed("contour_bounding_box", {})

    def centroid(self) -> Pipeline:
        """Compute the centroid (center of mass) of the contour.

        Measured on the same region as `area()` — the exterior minus the union
        of the hole rings — so overlapping or nested holes are not subtracted
        twice.

        Returns ``[x, y]``.

        Domain: contour → vector
        """
        return self._append_typed("contour_centroid", {})

    def close(self) -> Pipeline:
        """Join an open line's ends into the region it bounds. A line that
        returns to its first point (as ``boundary()`` draws one) drops the
        repeat, so ``close()`` undoes ``boundary()`` on a region without holes.
        A closed contour is refused.

        Domain: contour → contour
        """
        return self._append_typed("contour_close", {})

    def convex_hull(self) -> Pipeline:
        """Compute the convex hull of the contour.

        Domain: contour → contour
        """
        return self._append_typed("contour_convex_hull", {})

    def densify(self, max_segment_length: FloatOrExpr) -> Pipeline:
        """Add points so no edge is longer than *max_segment_length*: each edge is
        split into ``ceil(length / max_segment_length)`` equal parts, and every
        existing point is kept. A region's closing edges are split too.

        Domain: contour → contour

        Args:
            max_segment_length: The longest edge allowed, a finite length > 0 (literal
                or expression).
        """
        return self._append_typed(
            "contour_densify", {"max_segment_length": max_segment_length}
        )

    def largest(self, *, k: IntOrExpr = 1) -> Pipeline:
        """Keep the ``k`` largest contours of the set, by area: largest first,
        equal areas in their input order. A set of fewer keeps them all.

        Domain: contour → contour

        Args:
            k: How many contours to keep, >= 1 (literal or expression).
        """
        return self._append_typed("contour_largest", {"k": k})

    def offset(
        self, distance: FloatOrExpr, *, join: str | pl.Expr = "round"
    ) -> Pipeline:
        """Grow the set's regions by *distance* (negative: shrink them): every
        point within *distance* of their union, or inside it and at least
        ``-distance`` from its edge.

        The set is read as one union, so growing can merge regions and
        shrinking can split them or leave none: the result is always a set.
        Convex corners turn by *join*; concave ones stay sharp. Round arcs are
        polygons within 1/64 pixel of the true arc, or about ``distance / 2000``
        past a distance of 32 pixels. An open contour is refused.

        Domain: contour → contour

        Args:
            distance: How far to move the edge, in pixels: positive grows, negative
                shrinks (literal or expression).
            join: ``"round"`` (an arc about each corner), ``"miter"`` (the edges
                extended to meet, cut off past 4 times *distance*) or ``"bevel"`` (cut
                straight across). Accepts an expression.
        """
        return self._append_typed(
            "contour_offset", {"distance": distance, "join": join}
        )

    def perimeter(self) -> Pipeline:
        """Compute the perimeter (arc length) of the contour.

        Domain: contour → vector
        """
        return self._append_typed("contour_perimeter", {})

    def scale_contour(
        self, *, sx: FloatOrExpr, sy: FloatOrExpr, origin: str | pl.Expr = "centroid"
    ) -> Pipeline:
        """Scale the contour about *origin*.

        Domain: contour → contour

        Args:
            sx: X scale factor.
            sy: Y scale factor.
            origin: Point to scale about — ``"centroid"`` (center of mass),
                ``"bbox_center"`` (bounding-box center) or ``"origin"`` (the coordinate
                origin ``(0, 0)``). Accepts an expression for a per-row choice: which
                point the scale is measured from changes no output shape, rank or dtype.
        """
        return self._append_typed(
            "contour_scale", {"sx": sx, "sy": sy, "origin": origin}
        )

    def simplify(self, tolerance: FloatOrExpr) -> Pipeline:
        """Simplify the contour using the Douglas-Peucker algorithm.

        Domain: contour → contour

        Args:
            tolerance: Maximum distance from the original contour.
        """
        return self._append_typed("contour_simplify", {"tolerance": tolerance})

    def smooth(self, *, iterations: IntOrExpr = 1) -> Pipeline:
        """Round off corners by Chaikin's corner cutting: each pass replaces every
        edge by its points a quarter and three quarters along, doubling the
        point count. A region's rings are cut all the way round; an open line
        keeps its two ends, unless it returns to its first point (as
        ``boundary()`` draws one), when it is cut through it as a loop.

        Domain: contour → contour

        Args:
            iterations: Passes to make; 0 returns the contour as it is (literal or
                expression).
        """
        return self._append_typed("contour_smooth", {"iterations": iterations})

    def stroke(
        self,
        *,
        width: FloatOrExpr = 1.0,
        cap: str | pl.Expr = "round",
        join: str | pl.Expr = "round",
    ) -> Pipeline:
        """The region the set's paths cover when stroked, as disjoint regions:
        every point within ``width / 2`` of a path, its ends shaped by *cap*
        and its corners by *join*. Every member is read as its outline: an
        open line, capped at its ends (one returning to its first point, as
        ``boundary()`` draws one, is a closed path), and a region's rings,
        each a closed path with no ends. A ring of fewer than two points has
        no edge and covers nothing; a one-point line is a dot (its caps). The result is always a set, filled
        by ``rasterize()``: ``stroke(width=2).rasterize(...)`` draws lines and
        outlines. Round arcs are polygons within 1/64 pixel of the true arc,
        or about ``width / 4000`` past a width of 64 pixels.

        Domain: contour → contour

        Args:
            width: The stroke's full width in pixels, a finite width > 0 (literal or
                expression).
            cap: How an open line ends: ``"round"`` (a half disc), ``"square"`` (a half
                square) or ``"butt"`` (flat at its end point). Accepts an expression.
            join: How a path turns a corner: ``"round"``, ``"miter"`` (cut off past 4
                half-widths) or ``"bevel"``. Accepts an expression.
        """
        return self._append_typed(
            "contour_stroke", {"width": width, "cap": cap, "join": join}
        )

    def translate(self, *, dx: FloatOrExpr, dy: FloatOrExpr) -> Pipeline:
        """Translate the contour by an offset.

        Domain: contour → contour

        Args:
            dx: X offset (horizontal translation).
            dy: Y offset (vertical translation).
        """
        return self._append_typed("contour_translate", {"dx": dx, "dy": dy})

    def union_all(self) -> Pipeline:
        """The union of the set's regions, as disjoint regions: overlapping
        members merge and a hole another member covers is filled. The result
        is always a set. An open contour is refused.

        Domain: contour → contour
        """
        return self._append_typed("contour_union_all", {})

    def convolve2d(
        self,
        kernel: Sequence[FloatOrExpr],
        *,
        normalize: BoolOrExpr = False,
        border: str | pl.Expr = "replicate",
    ) -> Pipeline:
        """Apply generic 2D convolution with an arbitrary kernel.

        Domain: buffer → buffer

        Args:
            kernel: Flattened square kernel, row-major: its length is the square of an
                odd side (9 for 3×3, 25 for 5×5, ...), which is the kernel's size.
                **Each coefficient may be a literal float or a Polars expression**, so a
                batch can convolve with a different kernel per row; the length is
                structural.
            normalize: If True, divide output by the sum of absolute kernel values.
            border: Border handling mode (``"replicate"``, ``"zero"``, ``"reflect"``).

        Example:
            ```python
            >>> edge = Pipeline().source("image_bytes").convolve2d(
            ...     [-1, -1, -1, -1, 8, -1, -1, -1, -1]
            ... )
            ```
        """
        return self._append_typed(
            "convolve2d", {"kernel": kernel, "normalize": normalize, "border": border}
        )

    def coordinate_grid(self, *, normalized: BoolOrExpr = False) -> Pipeline:
        """The pixel coordinates of the image: an f32 ``[H, W, 2]`` buffer holding
        each pixel's centre ``(x + 0.5, y + 0.5)`` — the point ``rasterize``
        samples — or ``((x + 0.5) / W, (y + 0.5) / H)`` when *normalized*.

        Reads only the input's height and width, never its values, so it takes
        any dtype and channel count. The coordinates are in the frame of the
        buffer it follows: after a crop they start at the crop's corner. Combine
        them with ordinary ops for fields over positions (gradients, radial
        falloffs, vignettes).

        Domain: buffer → buffer

        Args:
            normalized: Divide x by the width and y by the height, so each lies in (0,
                1). Accepts a Polars expression for a per-row choice.

        Example:
            >>> dx2 = Pipeline().source("image_bytes").coordinate_grid().add_constant(-32.0).square()
        """
        return self._append_typed("coordinate_grid", {"normalized": normalized})

    def crop(
        self,
        *,
        top: IntOrExpr = 0,
        left: IntOrExpr = 0,
        height: IntOrExpr | None = None,
        width: IntOrExpr | None = None,
    ) -> Pipeline:
        """Extract a rectangular region.

        Domain: buffer → buffer

        Args:
            top: Top offset.
            left: Left offset.
            height: Crop height (None = to end).
            width: Crop width (None = to end).
        """
        return self._append_typed(
            "crop", {"top": top, "left": left, "height": height, "width": width}
        )

    def convert_color(self, *, from_space: str, to_space: str) -> Pipeline:
        """Convert between color spaces.

        Domain: buffer → buffer

        Args:
            from_space: Source color space (rgb, bgr, hsv, lab, ycbcr, gray).
            to_space: Target color space (rgb, bgr, hsv, lab, ycbcr, gray).

        Example:
            >>> pipe = Pipeline().source("image_bytes").convert_color(from_space="rgb", to_space="hsv")
        """
        return self._append_typed(
            "cvt_color", {"from_space": from_space, "to_space": to_space}
        )

    def dilate(
        self,
        *,
        ksize: IntOrExpr = 3,
        iterations: IntOrExpr = 1,
        footprint: str | pl.Expr = "square",
    ) -> Pipeline:
        """Morphological dilation: the local maximum over a footprint (a
        `ksize × ksize` square, or a disk), edges replicated. Requires
        single-channel input (e.g. after `.grayscale()` or `.threshold()`).

        Domain: buffer → buffer

        Args:
            ksize: Size of the structuring element (the square's side, the disk's
                diameter). Must be odd and >= 1. Accepts a Polars expression for per-row
                dynamic values.
            iterations: Number of times the operation is applied. Accepts a Polars
                expression for per-row dynamic values.
            footprint: The structuring element: ``"square"`` (``ksize x ksize``) or
                ``"disk"`` (the pixels within Euclidean distance ``ksize // 2`` of the
                centre). Accepts a Polars expression for a per-row choice.

        Example:
            >>> mask = Pipeline().source("image_bytes").grayscale().threshold(128).dilate(ksize=3)
        """
        return self._append_typed(
            "dilate", {"ksize": ksize, "iterations": iterations, "footprint": footprint}
        )

    def distance_transform(self, *, signed: BoolOrExpr = False) -> Pipeline:
        """Exact Euclidean distance transform of a mask: an f32 image of the same
        shape. Requires single-channel input.

        A pixel is foreground when it is non-zero (NaN included). Unsigned, each
        foreground pixel holds the distance from its centre to the nearest
        background pixel's centre and the background holds 0, as
        ``cv2.distanceTransform(DIST_L2, DIST_MASK_PRECISE)`` and
        ``scipy.ndimage.distance_transform_edt`` compute. Signed, every pixel
        holds its distance to the boundary between the two classes, the pixel
        edges ``extract_contours`` traces: negative inside, positive outside
        (as ``.point.signed_distance_to_contour``), ``±(d - 0.5)`` for the
        centre distance ``d`` to the nearest pixel of the other class. When a
        class has no pixel at all, the distance to it is infinite.

        Domain: buffer → buffer

        Args:
            signed: Signed distance to the mask's boundary (negative inside) instead of
                each foreground pixel's distance to the background. Accepts a Polars
                expression for a per-row choice.

        Example:
            >>> sdf = Pipeline().source("image_bytes").grayscale().threshold(128).distance_transform(signed=True)
        """
        return self._append_typed("distance_transform", {"signed": signed})

    def equalize_histogram(self) -> Pipeline:
        """Apply histogram equalization for contrast enhancement: map each pixel
        through the normalized CDF, per channel. Output is U8.

        Domain: buffer → buffer


        Example:
            >>> eq = Pipeline().source("image_bytes").grayscale().equalize_histogram()
        """
        return self._append_typed("equalize_histogram", {})

    def erode(
        self,
        *,
        ksize: IntOrExpr = 3,
        iterations: IntOrExpr = 1,
        footprint: str | pl.Expr = "square",
    ) -> Pipeline:
        """Morphological erosion: the local minimum over a footprint (a
        `ksize × ksize` square, or a disk), edges replicated. Requires
        single-channel input (e.g. after `.grayscale()` or `.threshold()`).

        Domain: buffer → buffer

        Args:
            ksize: Size of the structuring element (the square's side, the disk's
                diameter). Must be odd and >= 1. Accepts a Polars expression for per-row
                dynamic values.
            iterations: Number of times the operation is applied. Accepts a Polars
                expression for per-row dynamic values.
            footprint: The structuring element: ``"square"`` (``ksize x ksize``) or
                ``"disk"`` (the pixels within Euclidean distance ``ksize // 2`` of the
                centre). Accepts a Polars expression for a per-row choice.

        Example:
            >>> mask = Pipeline().source("image_bytes").grayscale().threshold(128).erode(ksize=3)
        """
        return self._append_typed(
            "erode", {"ksize": ksize, "iterations": iterations, "footprint": footprint}
        )

