    def histogram(
        self,
        *,
        bins: IntOrExpr | Sequence[float] = 256,
        range: Sequence[FloatOrExpr] | None = None,
        closed: str = "left",
        output: str = "buckets",
    ) -> Pipeline:
        """Compute pixel value histogram.

        Bins follow ``numpy.histogram``: a value outside the range or the edges
        is in no bin (not counted; ``"quantized"`` gives it the index one past the
        last bin), as is NaN. Infinite outer edges are open bounds, e.g.
        ``bins=[-inf, 0, 10, inf]`` keeps every value.

        Domain: buffer → vector; with ``output="quantized"``: buffer → buffer

        Args:
            bins: Number of bins (default 256), a Polars expression for per-row dynamic
                bin count, or an explicit list of non-decreasing bin edges (the outer
                ones may be infinite).
            range: (min, max) tuple, finite. Auto-detected if None, widened to hold
                every value.
            closed: "left" or "right" interval inclusiveness (default "left").
            output: "buckets" (list of structs), "counts" (bin counts), "normalized"
                (sum to 1.0), "quantized" (pixel indices), "edges" (bin edges).

        Example:
            >>> Pipeline().source("image_bytes").grayscale().histogram(bins=8)
        """
        return self._append_typed(
            "histogram",
            {"bins": bins, "range": range, "closed": closed, "output": output},
        )

    def invert(self) -> Pipeline:
        """Invert values, keeping the dtype: `MAX + MIN - x` for an integer
        (`255 - x` for u8, `-1 - x` for a signed dtype), `1 - x` for a float.

        Domain: buffer → buffer
        """
        return self._append_typed("invert", {})

    def label_reduce(
        self,
        contours: pl.Expr,
        *,
        reduction: str | pl.Expr = "max",
        region_mode: str | pl.Expr = "interior",
    ) -> Pipeline:
        """Score contour regions against the current buffer values.

        This is the buffer-space variant of label reduction. It accepts contours
        via a Polars expression and returns one score per contour.

        Pixels are sampled at their centres. A contour with no area (a point or
        a line) or whose region catches no pixel centre (a sub-pixel contour) is
        scored on the pixels its outline passes through, in every region mode,
        rather than as 0.0.

        Domain: buffer → vector

        Args:
            contours: Contour-set expression (`List[Contour]`) to score.
            reduction: Reduction over contour region values (`"max"`, `"mean"`,
                `"sum"`).
            region_mode: Region selection mode. ``"interior"`` — only pixels strictly
                inside the contour polygon. ``"boundary"`` — interior pixels *plus*
                pixels whose centre lies on the contour boundary. ``"bbox"`` — all
                pixels within the bounding box.
        """
        return self._append_typed(
            "label_reduce",
            {"contours": contours, "reduction": reduction, "region_mode": region_mode},
        )

